from pathlib import Path
import json,csv
P=Path(__file__).resolve().parent;e=json.loads((P/'edits.json').read_text());n=json.loads((P/'notes.json').read_text());tt=json.loads((P/'titles.json').read_text())
def p(a,k,t):e[f'A{a:04d}-B{k:04d}']=t
p(555,2,'四王议会是影月苍狼军团由四名连长组成的顾问议会，成员在军团内的权威仅次于荷鲁斯本人。不过，它没有正式的法定权力，处于指挥体系之外，所设职位也只适用于军团内部。大远征末期，议会由以泽凯尔·阿巴顿、“小荷鲁斯”阿西曼德、塔里克·托加顿和加维尔·洛肯组成。')
p(555,5,'关于四王议会的起源，资料可能存在矛盾。加维尔·洛肯称，它自军团初创便已存在，至少有两百年历史；但塔里克·托加顿后来告诉他，议会是从军团的非正式战士结社中衍生而来的。瑟加尔·塔戈斯特连长又称，战士结社是在影月苍狼首次造访戴文后才建立的。若后者属实，四王议会当时便只有约六十年历史。')
p(555,7,'据宣讲师梅梅德所说，“mournival”是古老法兰语中的一个词，指纸牌游戏中一手持有四张人头牌，也就是绘有人物头像的宫廷牌。这通常被视为一副胜牌。')
p(555,9,'议会的职责，是就战争与外交的各个方面向荷鲁斯进言，在他需要时配合摆出政治姿态，监督军团的道德风貌，并引导其思想。')
p(555,11,'每位成员都以不同的月相徽记区分身份，徽记刻在头盔右目镜上方。叛乱前最后一届四王议会采用如下月相：')
p(555,15,'托加顿——凸月。')
p(555,21,'乌兰诺远征结束、荷鲁斯升任战帅后不久，哈斯塔·塞扬努斯连长委托银匠制作四枚银戒，供自己与其他三位议会成员佩戴，每枚分别代表一种月相。然而，银匠被瑟加尔·塔戈斯特连长杀死后，塞扬努斯的戒指意外损毁；其余三枚是否交到阿巴顿、托加顿与阿西曼德手中，至今不明。')
p(555,23,'荷鲁斯遭混沌爪牙腐化后，四王议会也随之分裂：阿巴顿与阿西曼德追随深爱的原体，洛肯与托加顿则继续忠于帝皇。忠诚派在伊斯塔万三号的覆灭，使议会成员之间的兄弟情谊，首次遭到如此严重的撕裂。')
p(555,25,'伊斯塔万三号之战后，荷鲁斯·阿西曼德提议重建四王议会，补入两名成员。经过商议与实战考验，他和阿巴顿选定了法库斯·凯博与格雷尔·诺克图阿。泰拉围城期间，议会在土星之墙突袭的惨败中几乎全军覆没，只有阿巴顿幸存。此后，四王议会事实上不复存在，虽未正式宣布废止。')
p(555,28,'已知各届四王议会成员如下：')
p(555,34,'以泽凯尔·阿巴顿、荷鲁斯·阿西曼德、塔里克·托加顿、加维尔·洛肯——63-19之战后至荷鲁斯之乱初期的四王议会。')
p(555,40,'其他任职时间不详的成员包括：')
p(555,49,'据说，入选四王议会者都被同袍视为最优秀的连长；理想情况下，四人的性格应鲜明各异，又彼此互补。因此，也可用古代“四体液说”来解读他们，小说本身亦使用了相关措辞。依照文本的人物塑造与描写，托加顿对应多血质，阿巴顿对应胆汁质，阿西曼德对应抑郁质，洛肯对应黏液质。')
p(555,51,'洛肯的前任、“完美连长”哈斯塔·塞扬努斯，则被描述为性情各方面都均衡调和。按照古代体液学说，各种体液达到完美平衡，便会形成理想人格。')
p(555,53,'另外，原文还指出一个可供对照的神话意象：在古埃及神话中，天空神荷鲁斯有四位性情各异的儿子，据说共同构成他的灵魂。')
p(556,7,'这些黑甲终结者是军团的骄傲，担任突击的“矛尖”，专攻战斗最激烈之处。他们组成声名显赫的第一连，通常负责摧毁敌方核心，或对其指挥与控制体系实施斩首打击。他们深受荷鲁斯青睐，由第一连长以泽凯尔·阿巴顿直接统率。“加斯塔林”之名，源于帝国建立之前科索尼亚的一个强大帮派。')
p(556,11,'泰拉之战中，阿巴顿突袭土星之门失败，大批加斯塔林被忠诚派消灭，部队损失惨重。荷鲁斯败于帝皇之后，赫拉斯·赛卡率领尚能保持神志、服从命令的加斯塔林残部，遵照阿巴顿的命令撤离太阳系。')
p(556,13,'荷鲁斯之乱结束后，加斯塔林在黑色军团中的地位由绝望使者接替。不过，加斯塔林本身，至少其残部，仍是黑色军团终结者精锐的一部分。')
p(556,18,'法库斯·凯博连长。')
p(556,20,'赫拉斯·赛卡连长——凯博在泰拉围城中被认为阵亡后，接掌部队。')
p(557,2,'掠夺者攻击小队，是荷鲁斯之子在大远征与荷鲁斯之乱时期使用的特种星际战士编队。')
p(557,5,'他们体现了军团独有的作战方式，深受科索尼亚部落战争影响。掠夺者擅长迅猛突袭，以重创敌人、瘫痪其战斗力，击杀首领，并无情消灭落单之敌。遵循科索尼亚帮派传统，每支掠夺者部队实际上都是独立战帮，成员更多依靠个人发挥，而非严整的士兵式协同。')
p(557,7,'Sons of Horus Reaver Chieftain 荷鲁斯之子掠夺者首领')
p(557,9,'掠夺者战士有时会像突击战士一样，配备跳跃背包。')
p(557,11,'Reaver Attack Squad 掠夺者攻击小队')
p(557,13,'泰拉之战中，阿巴顿突袭土星之门失败，多支掠夺者小队被忠诚派消灭。围城后期，马拉博率掠夺者发动突袭，攻占了罗格·多恩的指挥中心巴布要塞。')
p(557,14,'Notable Reavers 著名掠夺者战士')
p(557,16,'德拉尔——泰拉之战期间担任作战连长与首领。')
p(557,18,'卡鲁斯·埃卡顿——卡图兰掠夺者小队连长。')
p(557,27,'Catulan Reaver Squad 卡图兰掠夺者小队')
p(557,28,'Cthonae Reaver Squad 科索尼亚掠夺者小队')
p(557,29,'Heathens Reaver Squad 异教徒掠夺者小队')
tt['557']='掠夺者攻击小队 Reaver Attack Squad'
p(559,2,'检察官教团，又称“洗劫者”（Vor Nergeth），是荷鲁斯之乱时期怀言者的药剂师组织。然而，这些检察官并不以医治伤员为职志，而是在战场上搜寻阵亡或负伤的忠诚派军团战士，利用亵渎他们的仪式召唤恶魔。')
p(559,4,'A Procurator and his attending Procurants 一名检察官及随侍的检察员')
p(559,7,'检察官尤其觊觎忠诚派的基因存收腺，因为它们对最强大、最凶暴的亚空间生灵格外有吸引力。召唤时，检察官一边撕出祭品的基因存收腺，一边低诵诅咒经文，祈求恶魔相助。被称为“检察员”的怀言者学徒会在旁协助。他们也是狂热的护卫，将导师犯下的暴行视为蒙受赐福之举，因此对导师忠心耿耿。当检察官向着垂死祭品吟诵时，检察员便在受害者身上刻出秘奥符文，削弱隔绝亚空间的帷幕。如此一来，与检察官达成交易的恶魔便能进入现实空间，扑向怀言者的敌人。仪式还会把窃取的生命力灌注给检察官与检察员，使他们恢复活力。但有时，受召恶魔会嫌祭品不配献给自己，转而攻击叛徒军团以及周围所有人。')
p(559,9,'检察官除将受害者献祭给恶魔，也会割取其肢体作为战利品，装饰动力甲。检察官及其检察员还可装备战鹰跳跃背包参战。')
n.update({'A0555-B0007':'iterator 为宣讲师职衔，Memed 为人名暂译梅梅德；原译迭代模因误将两者当作普通词。Franc 按世界内语言名暂作法兰语，不直接认定现代法语。','A0555-B0015':'Gibbous Moon 指亮面超过半圆、未满圆的凸月，不必然指盈月，已修正。','A0555-B0023':'本段英文称忠诚派在伊斯塔万三号死亡，与其他篇目中洛肯幸存的叙述不完全吻合；此处按群体覆灭叙述，不据此断言洛肯确已战死。','A0555-B0049':'英文 complimentary 应为 complementary 的误写，依明确语境译彼此互补。体液说及后文神话联想均为原文解读，不作为现行科学或独立核实的设定结论。','A0556-B0007':'in the days before the Imperium 指帝国出现前的年代，原译几天前过度字面化。','A0556-B0013':'本段原英文 Black Legi on 内部空格异常，读作 Black Legion；英文原貌保留，中文正常翻译。','A0556-B0020':'apparent death 为看来已经死亡或被认为阵亡，不等于有意假死。','A0557-B0013':'Saturnine Gate 统一土星之门，原译永恒之门误认地点；0556原译泰拉之门同样改正。','A0557-B0002':'与0554部队表统一 Reaver 为掠夺者，原收割者在原译对照保留；不同于原铸 Reiver，英文拼写分别保存。','A0559-B0007':'英文 arcane ruins 结合在祭品身上刻画及召唤语境，显系 runes 的拼写错误，中文修正为秘奥符文，并保留英文原字。','A0559-B0002':'Procurator／Procurant 暂沿现稿检察官／检察员，属于怀言者仪式职衔，不能据字面误认为帝国司法官；Vor Nergeth 沿洗劫者待核。'})
rows=list(csv.DictReader((P/'terms.tsv').open(),delimiter='\t'));cols=list(rows[0]);by={r[cols[0]].casefold():r for r in rows}
for en,zh in [('Iterator','宣讲师'),('Memed','梅梅德'),('Serghar Targost','瑟加尔·塔戈斯特'),('Hastur Sejanus','哈斯塔·塞扬努斯'),('Grael Noctua','格雷尔·诺克图阿'),('Hellas Sycar','赫拉斯·赛卡'),('Bringers of Despair','绝望使者'),('Order of the Procurators','检察官教团'),('Procurator','检察官'),('Procurant','检察员'),('Vor Nergeth','洗劫者'),('Warhawk Jump Pack','战鹰跳跃背包'),('Saturnine Wall','土星之墙')]:
 by.setdefault(en.casefold(),dict(zip(cols,[en,zh,'暂定·官方待核','所给英文底稿','篇0555—0559','保留具体军团与时代语境，原译异写另存对照。'])))
with (P/'terms.tsv').open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=cols,delimiter='\t');w.writeheader();w.writerows(by.values())
for fn,obj in [('edits.json',e),('notes.json',n),('titles.json',tt)]:(P/fn).write_text(json.dumps(obj,ensure_ascii=False,indent=2))
rv=set(json.loads((P/'reviewed.json').read_text()))|{555,556,557,559};(P/'reviewed.json').write_text(json.dumps(sorted(rv)))
print('complete 555-557 and559',len(e))
